<script lang="ts">
 import {auth} from '#lib/auth.svelte.ts';import {anyApi} from 'convex/server';import locations from '#lib/data/nigeria-locations.json';
 const places=locations as Record<string,string[]>;
 let email=$state(''),password=$state(''),fullName=$state(''),whatsapp=$state(''),dob=$state(''),sex=$state(''),region=$state(''),lga=$state(''),busy=$state(false),message=$state('');
 async function redeem(e:SubmitEvent){e.preventDefault();if(!auth.client)return;busy=true;message='';try{const result=await auth.client.mutation(anyApi.testers.redeem,{email,password,profile:{fullName,whatsapp,dob,sex,state:region,lga}});message=result.error??'Your individual tester access is active for seven days. Open the fixture board.';password='';}catch(e){message=(e as Error).message;}finally{busy=false;}}
</script>
<svelte:head><title>Tester invitation — PuntersEdge</title><meta name="robots" content="noindex"/></svelte:head>
<section class="surface mx-auto max-w-2xl p-5 sm:p-8"><h1 class="text-3xl font-bold">Your tester invitation</h1><p class="mt-3 text-haze">Each tester has a separate verified account, profile and access period. Your personal email is your sign-in identity.</p>
{#if !auth.signedIn}<div class="mt-5 flex flex-wrap gap-3"><a class="btn-primary" href="/signup">Create your personal account</a><a class="btn-ghost" href="/login?next=/tester">Sign in</a></div><p class="mt-4 text-sm text-haze">Verify your personal email, then return here to redeem the shared invitation.</p>{:else}<form class="mt-5 grid min-w-0 gap-4" onsubmit={redeem}><p class="break-words text-sm text-model">Verified personal email: {auth.viewer?.email}</p>
{#each [['Invitation email','email'],['Invitation password','password'],['Full name','fullName'],['WhatsApp number (country code)','whatsapp']] as [label,key]}<label class="block min-w-0 text-sm">{label}<input required type={key==='password'?'password':key==='email'?'email':'text'} class="mt-1 min-h-11 w-full min-w-0 rounded-xl bg-ink p-3 ring-1 ring-line" value={key==='email'?email:key==='password'?password:key==='fullName'?fullName:whatsapp} oninput={e=>{const v=e.currentTarget.value;if(key==='email')email=v;else if(key==='password')password=v;else if(key==='fullName')fullName=v;else whatsapp=v;}} /></label>{/each}
<label class="text-sm">Date of birth (18+)<input required type="date" bind:value={dob} class="mt-1 min-h-11 w-full min-w-0 rounded-xl bg-ink p-3 ring-1 ring-line"/></label>
<label class="text-sm">Sex<select required bind:value={sex} class="mt-1 min-h-11 w-full rounded-xl bg-ink p-3 ring-1 ring-line"><option value="">Select</option><option value="female">Female</option><option value="male">Male</option><option value="prefer_not_to_say">Prefer not to say</option></select></label>
<label class="text-sm">State / FCT<select required bind:value={region} onchange={()=>lga=''} class="mt-1 min-h-11 w-full rounded-xl bg-ink p-3 ring-1 ring-line"><option value="">Select state</option>{#each Object.keys(places).sort() as s}<option>{s}</option>{/each}</select></label>
<label class="text-sm">Local government area<select required bind:value={lga} class="mt-1 min-h-11 w-full rounded-xl bg-ink p-3 ring-1 ring-line"><option value="">Select LGA</option>{#each places[region]??[] as area}<option>{area}</option>{/each}</select></label><button class="btn-primary" disabled={busy}>{busy?'Saving your profile…':'Save profile & activate invitation'}</button><a href="/board" class="btn-ghost">Open fixture board</a></form>{/if}{#if message}<p role="status" class="mt-4 text-sm">{message}</p>{/if}</section>
